{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A short intensive to reframe daily rhythm</title>
  <meta name="description" content="A focused intensive blending outcomes, micro-habits and frameworks for steadier energy and clearer priorities." />
  <link rel="icon" href="data:;base64,iVBORw0KGgo=" />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="container">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/about.html">About</a>
        <a href="/programs.html">Programs</a>
        <a href="/services.html">Offerings</a>
        <a href="/pricing.html">Plans</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-expanded="false" aria-label="Menu">☰</button>
      </nav>
    </div>
    <svg class="pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
  </header>

  <main>
    <!-- Section: Hero (first) -->
    <section id="hero" class="hero container">
      <div class="hero-content">
        <h1 class="title">Shape your next week, one clear step at a time.</h1>
        <p class="lead">A focused, outcome-oriented intensive built around simple daily practices, clear frameworks, and measurable micro-habits.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start the intensive</a>
          <button id="tryExerciseBtn" class="btn ghost">Try a quick exercise</button>
        </div>
        <ul class="quick-notes">
          <li>Outcome-led frameworks, not prescriptions.</li>
          <li>7-day challenge you can print and keep.</li>
          <li>Tools for habit momentum and scheduling.</li>
        </ul>
      </div>
      <div class="hero-card">
        <div class="card-intro">
          <strong>Free starter:</strong>
          <p>Generate a 7-day micro-habit challenge and print a checklist to carry with you.</p>
          <button id="openHabitBuilder" class="btn">Build a 7-day challenge</button>
        </div>
      </div>
    </section>

    <!-- Section: Diagnostic (second) -->
    <section id="diagnostic" class="diagnostic container">
      <h2>Begin with a short diagnostic</h2>
      <p class="muted">A five-question reflection that surfaces where energy and clarity leak each day. Not clinical—practical insights you can use now.</p>
      <form id="diagForm" class="diag-form">
        <label>1) How often do you feel rushed across the day?
          <select name="q1" required>
            <option value="0">Rarely</option>
            <option value="1">Sometimes</option>
            <option value="2">Often</option>
            <option value="3">Almost always</option>
          </select>
        </label>
        <label>2) How clear are your top three priorities each morning?
          <select name="q2" required>
            <option value="0">Clear</option>
            <option value="1">Somewhat</option>
            <option value="2">Unclear</option>
            <option value="3">Absent</option>
          </select>
        </label>
        <label>3) How consistent are your sleep and wake times?
          <select name="q3" required>
            <option value="0">Consistent</option>
            <option value="1">Mostly</option>
            <option value="2">Irregular</option>
            <option value="3">Very irregular</option>
          </select>
        </label>
        <label>4) How often do you finish the day with a short reflection or plan?
          <select name="q4" required>
            <option value="0">Usually</option>
            <option value="1">Sometimes</option>
            <option value="2">Rarely</option>
            <option value="3">Never</option>
          </select>
        </label>
        <label>5) How clear is the reason you do each key task?
          <select name="q5" required>
            <option value="0">Clear</option>
            <option value="1">Somewhat</option>
            <option value="2">Often unclear</option>
            <option value="3">Not at all</option>
          </select>
        </label>
        <div class="diag-actions">
          <button type="submit" class="btn primary">Get insight</button>
          <button type="button" id="clearDiag" class="btn ghost">Reset</button>
        </div>
      </form>
      <div id="diagResult" class="diag-result" aria-live="polite"></div>
    </section>

    <!-- Section: Micro Habits (third) -->
    <section id="micro_habits" class="micro container">
      <h2>Micro habits you can fold into any day</h2>
      <p class="muted">Short actions, structured to create momentum. Choose from ritual starters, energy resets, or clarity cues.</p>
      <div class="habit-grid">
        <div class="habit">
          <h3>Ritual Starter</h3>
          <p>Two minutes to orient your morning with an intention and a tiny anchor task.</p>
          <button class="btn" data-habit="Ritual Starter">Use</button>
        </div>
        <div class="habit">
          <h3>Energy Reset</h3>
          <p>60 seconds of focused breathing and a short stretch to break reactive loops.</p>
          <button class="btn" data-habit="Energy Reset">Use</button>
        </div>
        <div class="habit">
          <h3>Clarity Cue</h3>
          <p>A single question to ask before any meeting or task so you keep intention in view.</p>
          <button class="btn" data-habit="Clarity Cue">Use</button>
        </div>
      </div>
      <p class="muted">Want a printable plan? Use the habit builder to craft a 7-day sequence tailored to a single outcome.</p>
    </section>

    <!-- Section: Plan (fourth) -->
    <section id="plan" class="plan container">
      <h2>How the intensive is shaped</h2>
      <div class="plan-steps">
        <div class="step">
          <h4>1 — Map</h4>
          <p>We anchor on a near-term outcome and the few behaviors that directly feed it.</p>
        </div>
        <div class="step">
          <h4>2 — Small experiments</h4>
          <p>Three micro-habits over seven days to test what sticks quickly.</p>
        </div>
        <div class="step">
          <h4>3 — Rhythm</h4>
          <p>Schedules and prompts to make tiny wins repeatable without friction.</p>
        </div>
      </div>
      <a class="btn outline" href="/programs.html">Explore programs</a>
    </section>

    <!-- Section: Pricing (fifth) -->
    <section id="pricing" class="pricing container">
      <h2>Plans framed for impact</h2>
      <p class="muted">Pricing reflects focused assistance that directs behavior and measurement, not endless sessions.</p>
      <div class="pricing-grid">
        <div class="price-card">
          <h3>Week Sprint</h3>
          <p class="price">$249</p>
          <ul>
            <li>7-day micro-habit sequence</li>
            <li>Two short coaching touchpoints</li>
            <li>Printable checklist + next-step plan</li>
          </ul>
          <a class="btn primary" href="/pricing.html#week">Choose</a>
        </div>
        <div class="price-card">
          <h3>Focused Intensive</h3>
          <p class="price">$799</p>
          <ul>
            <li>4-week outcome roadmap</li>
            <li>Custom daily micro-habit plan</li>
            <li>Weekly accountability check-ins</li>
          </ul>
          <a class="btn primary" href="/pricing.html#intensive">Choose</a>
        </div>
        <div class="price-card">
          <h3>Team Mini-Rhythm</h3>
          <p class="price">Custom</p>
          <ul>
            <li>Group practices and rituals</li>
            <li>Shared habit trackers</li>
            <li>On-call framework design</li>
          </ul>
          <a class="btn primary" href="/contact.html">Inquire</a>
        </div>
      </div>
    </section>

    <!-- Section: CTA (sixth) -->
    <section id="cta" class="cta container">
      <h2>Ready to reframe your week?</h2>
      <p>One focused commitment. Measurable shifts. A clear next action at the end.</p>
      <div class="cta-actions">
        <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="btn ghost">Ask a question</a>
      </div>
      <p class="muted">Prefer a quick call? Reach us at <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <div class="footer-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Serving {{CITY}}, {{STATE}} and remote clients worldwide.</p>
      </div>
      <div class="footer-right">
        <nav class="foot-nav">
          <a href="/about.html">About</a>
          <a href="/testimonials.html">Stories</a>
          <a href="/book.html">Book</a>
          <a href="/contact.html">Contact</a>
        </nav>
        <small class="muted">© <span id="year"></span> {{BUSINESS_NAME}}</small>
      </div>
    </div>
  </footer>

  <!-- Printable checklist modal (hidden until generated) -->
  <div id="checklistModal" class="modal" aria-hidden="true">
    <div class="modal-panel">
      <button class="modal-close" aria-label="Close">×</button>
      <div id="checklistContent"></div>
      <div class="modal-actions">
        <button id="printChecklist" class="btn primary">Print checklist</button>
        <button id="downloadChecklist" class="btn ghost">Download TXT</button>
      </div>
    </div>
  </div>

  <!-- Guided exercise modal -->
  <div id="exerciseModal" class="modal" aria-hidden="true">
    <div class="modal-panel exercise-panel">
      <button class="modal-close" aria-label="Close">×</button>
      <h3 id="exerciseTitle">Quick practice</h3>
      <div id="exerciseBody" class="exercise-body">
        <!-- Filled by JS -->
      </div>
      <div class="modal-actions">
        <button id="exerciseStart" class="btn primary">Start</button>
        <button id="exerciseStop" class="btn ghost">Stop</button>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
